require "json"
require "net/http"
require "socket"
require "uri"
require "websocket/driver"

class CDPSocket
  attr_reader :url, :io

  def initialize(url)
    @url = url
    uri = URI(url)
    @io = TCPSocket.new(uri.host, uri.port)
  end

  def write(data)
    @io.write(data)
  end
end

class CDP
  def initialize(url)
    @socket = CDPSocket.new(url)
    @messages = Queue.new
    @opened = false
    @driver = WebSocket::Driver.client(@socket)
    @driver.on(:open) { @opened = true }
    @driver.on(:message) { |event| @messages << JSON.parse(event.data) }
    @driver.on(:error) { |event| raise "websocket error: #{event.message}" }
    @driver.start
    until @opened
      @driver.parse(@socket.io.readpartial(65_536))
    end
    @next_id = 0
  end

  def command(method, params = {})
    @next_id += 1
    command_id = @next_id
    @driver.text(JSON.generate(id: command_id, method: method, params: params))
    loop do
      IO.select([@socket.io], nil, nil, 10) or raise "timeout waiting for #{method}"
      @driver.parse(@socket.io.readpartial(65_536))
      until @messages.empty?
        message = @messages.pop(true)
        next unless message["id"] == command_id
        raise message["error"].inspect if message["error"]
        return message.fetch("result", {})
      end
    end
  end

  def evaluate(expression)
    result = command("Runtime.evaluate", { expression: expression, returnByValue: true, awaitPromise: true })
    result.dig("result", "value")
  end
end

