require "json"
require "net/http"
require "websocket/driver"
require "socket"
require "uri"

class InspectSocket
  attr_reader :url, :io
  def initialize(url)
    @url = url
    u = URI(url)
    @io = TCPSocket.new(u.host, u.port)
  end
  def write(data) = @io.write(data)
end

class InspectCDP
  attr_reader :events
  def initialize(url)
    @socket = InspectSocket.new(url)
    @queue = Queue.new
    @events = []
    @opened = false
    @driver = WebSocket::Driver.client(@socket)
    @driver.on(:open) { @opened = true }
    @driver.on(:message) { |e| @queue << JSON.parse(e.data) }
    @driver.on(:error) { |e| warn e.message }
    @driver.start
    @driver.parse(@socket.io.readpartial(65_536)) until @opened
    @next_id = 0
  end

  def command(method, params = {})
    @next_id += 1
    id = @next_id
    @driver.text(JSON.generate(id: id, method: method, params: params))
    loop do
      IO.select([@socket.io], nil, nil, 5) or raise "timeout waiting for #{method}"
      @driver.parse(@socket.io.readpartial(65_536))
      until @queue.empty?
        message = @queue.pop(true)
        if message["id"] == id
          raise message["error"].inspect if message["error"]
          return message.fetch("result", {})
        end
        @events << message
      end
    end
  end

  def evaluate(script)
    command("Runtime.evaluate", { expression: script, returnByValue: true, awaitPromise: true }).dig("result", "value")
  end
end

