  updateTimerDisplay() {
    if (!this.timerDeadline) return
    const secondsLeft = Math.max(0, Math.ceil((this.timerDeadline - Date.now()) / 1000))
    const minutes = Math.floor(secondsLeft / 60)
    const seconds = String(secondsLeft % 60).padStart(2, "0")
    this.timerTarget.textContent = `${minutes}:${seconds}`

    if (secondsLeft === 0) {
      this.clearTimerInterval()
      this.finishExpiredQuestion()
    }
  }

